function formatQuestion(q) {
  const choices = q.choices.map((c) => JSON.stringify(c)).join(", ");
  return `{ "id": ${JSON.stringify(q.id)}, "word": ${JSON.stringify(q.word)}, "answer": ${JSON.stringify(q.answer)}, "choices": [${choices}], "category": ${JSON.stringify(q.category)}, "difficulty": ${JSON.stringify(q.difficulty)} }`;
}

const pool = JSON.parse(readFileSync(QUESTIONS_PATH, "utf8"));
const existingWords = new Set(pool.questions.map((q) => q.word.toLowerCase()));
const existingIds = new Set(pool.questions.map((q) => q.id));

const conflicts = [];
const seenInBatch = new Set();
const seenWordsInBatch = new Set();
for (const q of NEW_QUESTIONS) {
  if (existingIds.has(q.id)) conflicts.push(`id ${q.id} already exists in pool`);
  if (seenInBatch.has(q.id)) conflicts.push(`id ${q.id} duplicated within new batch`);
  seenInBatch.add(q.id);
  const wkey = q.word.toLowerCase();
  if (existingWords.has(wkey)) conflicts.push(`word "${q.word}" already exists in pool`);
  if (seenWordsInBatch.has(wkey)) conflicts.push(`word "${q.word}" duplicated within new batch`);
  seenWordsInBatch.add(wkey);
}
if (conflicts.length) {
  console.error("Conflicts detected:");
  conflicts.forEach((c) => console.error(`  - ${c}`));
  process.exit(1);
}

const merged = { ...pool, questions: [...pool.questions, ...NEW_QUESTIONS] };
const body = merged.questions
  .map((q, i) => `    ${formatQuestion(q)}${i < merged.questions.length - 1 ? "," : ""}`)
  .join("\n");
const out = `{\n  "version": ${merged.version},\n  "questions": [\n${body}\n  ]\n}\n`;

writeFileSync(QUESTIONS_PATH, out);
console.log(
  `Added ${NEW_QUESTIONS.length} questions. Total now: ${merged.questions.length}`,
);
